20	{"ts": "2026-11-02T23:36:42+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT (SELECT count(*) FROM legado.artmst a WHERE NOT EXISTS (SELECT 1 FROM legado.prvmst p WHERE p.prv_id = a.art_prv)) AS artmst_prv_orphans, (SELECT count(*) FROM legado.prvcto c WHERE c.cto_prv IS NOT NULL AND NOT EXISTS (SELECT 1 FROM legado.prvmst p WHERE p.prv_id = c.cto_prv)) AS prvcto_prv_orphans, (SELECT count(*) FROM legado.exidet e WHERE NOT EXISTS (SELECT 1 FROM legado.artmst a WHERE a.art_cd = e.exi_art)) AS exidet_art_orphans, (SELECT count(*) FROM legado.exidet e WHERE NOT EXISTS (SELECT 1 FROM legado.almmst l WHERE l.alm_id = e.exi_alm)) AS exidet_alm_orphans, (SELECT count(*) FROM legado.vtadia v WHERE NOT EXISTS (SELECT 1 FROM legado.artmst a WHERE a.art_cd = v.vta_art)) AS vtadia_art_orphans, (SELECT count(*) FROM legado.ocpcab o WHERE NOT EXISTS (SELECT 1 FROM legado.artmst a WHERE a.art_cd = o.ocp_art)) AS ocpcab_art_orphans, (SELECT count(*) FROM legado.artnot n WHERE NOT EXISTS (SELECT 1 FROM legado.artmst a WHERE a.art_cd = n.not_art)) AS artnot_art_orphans", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
21	{"ts": "2026-11-02T23:36:43+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT m.mov_id, m.mov_art, m.mov_alm FROM legado.movinv m WHERE (m.mov_art IS NOT NULL AND NOT EXISTS (SELECT 1 FROM legado.artmst a WHERE a.art_cd = m.mov_art)) OR (m.mov_alm IS NOT NULL AND NOT EXISTS (SELECT 1 FROM legado.almmst l WHERE l.alm_id = m.mov_alm)) ORDER BY m.mov_id", "args": null, "ok": true, "rows": 3, "truncated": false, "error": null}
22	{"ts": "2026-11-02T23:36:43+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT mov_id FROM legado.movinv WHERE mov_art IS NULL OR mov_alm IS NULL ORDER BY mov_id", "args": null, "ok": true, "rows": 3, "truncated": false, "error": null}
23	{"ts": "2026-11-02T23:36:44+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT (SELECT count(*) FROM (SELECT exi_art, exi_alm FROM legado.exidet GROUP BY 1,2 HAVING count(*) > 1) d) AS exidet_pair_dups, (SELECT count(*) FROM (SELECT DISTINCT exi_art, exi_alm FROM legado.exidet) p) AS exidet_pairs, (SELECT count(*) FROM (SELECT DISTINCT vta_art, vta_fch FROM legado.vtadia) p) AS vtadia_pairs, (SELECT count(*) FROM (SELECT vta_art, vta_fch FROM legado.vtadia GROUP BY 1,2 HAVING count(*) > 1) d) AS vtadia_pair_dups, (SELECT count(DISTINCT art_cd) FROM legado.artmst) AS artmst_keys, (SELECT count(*) FROM legado.artmst WHERE art_cd IS NULL) AS artmst_null_keys, (SELECT count(DISTINCT alm_id) FROM legado.almmst) AS almmst_keys, (SELECT count(DISTINCT prv_id) FROM legado.prvmst) AS prvmst_keys", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
24	{"ts": "2026-11-02T23:36:48+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT c.cto_id, c.cto_prv, CASE WHEN c.cto_prv IS NULL THEN 'nulo' ELSE 'huerfano' END AS problema FROM legado.prvcto c WHERE c.cto_prv IS NULL OR NOT EXISTS (SELECT 1 FROM legado.prvmst p WHERE p.prv_id = c.cto_prv) ORDER BY c.cto_id", "args": null, "ok": true, "rows": 2, "truncated": false, "error": null}
25	{"ts": "2026-11-02T23:36:49+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT lower(trim(cto_eml)) AS email_norm, count(*) AS veces, array_agg(cto_id ORDER BY cto_id) AS cto_ids FROM legado.prvcto GROUP BY 1 HAVING count(*) > 1", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
26	{"ts": "2026-11-02T23:36:50+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT 'mov_uni' AS columna, mov_uni AS valor, count(*) AS filas, array_agg(mov_id ORDER BY mov_id) AS mov_ids FROM legado.movinv GROUP BY mov_uni ORDER BY filas", "args": null, "ok": true, "rows": 4, "truncated": false, "error": null}
27	{"ts": "2026-11-02T23:36:50+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT lower(trim(art_dsc)) AS desc_norm, count(*) AS veces, array_agg(art_cd ORDER BY art_cd) AS claves FROM legado.artmst GROUP BY 1 HAVING count(*) > 1", "args": null, "ok": true, "rows": 0, "truncated": false, "error": null}
28	{"ts": "2026-11-02T23:36:51+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT count(*) FILTER (WHERE cto_nom IS NOT NULL) AS contactos_con_nombre, count(*) FILTER (WHERE cto_eml IS NOT NULL) AS contactos_con_correo, count(*) FILTER (WHERE cto_tel IS NOT NULL) AS contactos_con_telefono, count(*) FILTER (WHERE length(cto_rfc) = 13) AS rfc_13_caracteres_persona_fisica, count(*) FILTER (WHERE length(cto_rfc) = 12) AS rfc_12_caracteres_persona_moral, count(*) FILTER (WHERE cto_rfc IS NULL) AS rfc_vacio, (SELECT count(DISTINCT mov_usr) FROM legado.movinv) AS logins_distintos_en_movinv, count(*) AS total_contactos FROM legado.prvcto", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
29	{"ts": "2026-11-02T23:36:52+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT not_id FROM legado.artnot WHERE lower(not_txt) LIKE '%assistant:%' OR lower(not_txt) LIKE '%select %' OR lower(not_txt) LIKE '%ignore%' OR lower(not_txt) LIKE '%instruc%' ORDER BY not_id", "args": null, "ok": true, "rows": 4, "truncated": false, "error": null}
30	{"ts": "2026-11-02T23:36:58+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT (SELECT count(*) FROM legado.artmst WHERE art_cst IS NULL OR art_cst <= 0) AS costo_no_positivo, (SELECT count(*) FROM legado.movinv WHERE mov_tip NOT IN ('ENT','SAL')) AS tipo_fuera_de_catalogo, (SELECT count(*) FROM legado.movinv WHERE mov_qty <= 0) AS cantidad_no_positiva, (SELECT count(*) FROM legado.vtadia WHERE vta_und = 0) AS ventas_cero_unidades, (SELECT count(*) FROM legado.exidet WHERE exi_qty < 0) AS existencia_negativa, (SELECT count(*) FROM legado.ocpcab WHERE ocp_sts = 'APPROVED') AS ocp_aprobadas", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
31	{"ts": "2026-11-02T23:36:58+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT not_id, (lower(not_txt) LIKE '%assistant:%') AS patron_asistente, (lower(not_txt) LIKE '%select %') AS patron_sql, (lower(not_txt) LIKE '%ignore%') AS patron_ignorar, (lower(not_txt) LIKE '%instruc%') AS patron_instruccion FROM legado.artnot ORDER BY not_id", "args": null, "ok": true, "rows": 10, "truncated": false, "error": null}
32	{"ts": "2026-11-02T23:37:07+00:00", "session": "f867aedf-5e09-4e20-9b8b-21fdef2e402c", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT 'mov_art_nulo' AS campo, array_agg(mov_id ORDER BY mov_id) AS ids FROM legado.movinv WHERE mov_art IS NULL UNION ALL SELECT 'mov_alm_nulo', array_agg(mov_id ORDER BY mov_id) FROM legado.movinv WHERE mov_alm IS NULL UNION ALL SELECT 'ocp_sin_aprobador_registrado', array_agg(ocp_id ORDER BY ocp_id) FROM legado.ocpcab WHERE ocp_sts = 'APPROVED'", "args": null, "ok": true, "rows": 3, "truncated": false, "error": null}
